/* The server is authoritative. Browser storage is used only for retryable actions. */
const isPilotage=location.pathname.startsWith('/pilotage');
const API_BASE=isPilotage?'/api/pilotage':'/api';
page=isPilotage?'dashboard':'client';
let syncing=false,lastRevision=-1,queueBusy=false;
const OUTBOX='click-eat-'+(isPilotage?'pilotage':'client')+'-outbox-v2';
function outbox(){try{return JSON.parse(localStorage.getItem(OUTBOX))||[]}catch{return[]}}
function accept(next,force=false){const changed=next.revision!==lastRevision||JSON.stringify(next.slots)!==JSON.stringify(state.slots)||Boolean(next.hold)!==Boolean(state.hold);state=next;lastRevision=next.revision;if(force||(changed&&!$('#modal').open&&!['INPUT','SELECT'].includes(document.activeElement?.tagName)))render();}
async function refresh(force=false){if(syncing)return;syncing=true;try{const r=await fetch(API_BASE+'/state',{cache:'no-store'});if(r.status===403&&isPilotage){const data=await r.json();renderAccess(data.error);return;}if(!r.ok)throw Error('Serveur indisponible');accept(await r.json(),force);$('#connection-error')?.remove();}catch(e){if(lastRevision<0)$('#app').innerHTML='<main><h1>Connexion au serveur</h1><p>Le serveur est temporairement indisponible. Nouvelle tentative automatique…</p></main>';else if(!$('#connection-error')){const banner=document.createElement('div');banner.id='connection-error';banner.setAttribute('role','status');banner.textContent='Connexion interrompue · Les validations cuisine seront envoyées au rétablissement.';banner.style.cssText='padding:14px;background:#fff2dc;text-align:center';$('#app').prepend(banner);}}finally{syncing=false;}}
async function send(action,payload,offlineAllowed=false){
 const existing=outbox().find(x=>x.action===action&&JSON.stringify(x.payload)===JSON.stringify(payload));
 const entry=existing||{requestId:crypto.randomUUID(),action,payload};
 if(!existing)localStorage.setItem(OUTBOX,JSON.stringify([...outbox(),entry]));
 try{let r,data;for(let attempt=0;attempt<12;attempt++){r=await fetch(API_BASE+'/action',{method:'POST',headers:{'Content-Type':'application/json','X-Click-Eat':'1'},body:JSON.stringify(entry)});data=await r.json();if(r.status!==202)break;toast('Votre demande n°'+data.sequence+' est dans la file.');await new Promise(resolve=>setTimeout(resolve,400));}if(r.status===202)throw Object.assign(Error('Votre demande reste dans la file. Cliquez à nouveau pour consulter son résultat.'),{server:true});if(!r.ok){if(r.status<500)localStorage.setItem(OUTBOX,JSON.stringify(outbox().filter(x=>x.requestId!==entry.requestId)));await refresh();throw Object.assign(Error(data.error||'Erreur serveur'),{server:true});}localStorage.setItem(OUTBOX,JSON.stringify(outbox().filter(x=>x.requestId!==entry.requestId)));accept(data.state,true);return data.result;}catch(e){if(e.server)throw e;if(offlineAllowed){toast('Action conservée sur cet appareil. Elle sera synchronisée au retour du réseau.');return {queued:true};}throw Error('Connexion interrompue. Réessayez la même action : elle ne sera pas exécutée deux fois.');}
}
async function replay(){if(queueBusy||!navigator.onLine)return;queueBusy=true;try{for(const e of outbox().filter(x=>['advance','delay'].includes(x.action))){try{await send(e.action,e.payload,true)}catch(err){toast('Action cuisine non appliquée : '+err.message);}}}finally{queueBusy=false;}}
async function safely(fn){try{await fn()}catch(e){toast(e.message)}}
const originalBind=bind;
bind=function(){originalBind();document.querySelectorAll('[data-stock]').forEach(b=>b.onclick=()=>safely(async()=>{await send('stock',{id:b.dataset.stock,qty:Number($('#stock-'+b.dataset.stock).value)});toast('Stock enregistré sur le serveur.')}));document.querySelectorAll('[data-rupture]').forEach(b=>b.onclick=()=>safely(async()=>{await send('stock',{id:b.dataset.rupture,qty:0});toast('Rupture enregistrée sur tous les appareils.')}));};
advance=id=>safely(async()=>{const order=state.orders.find(o=>o.id===id);const result=await send('advance',{id,expectedStatus:order.status},true);if(!result.queued)toast('Commande mise à jour.');});
delay=id=>safely(async()=>{const result=await send('delay',{id},true);if(!result.queued)toast('Retrait décalé de 5 min · notification simulée.');});
detail=id=>{const o=state.orders.find(o=>o.id===id);modal(`<h2>Commande #${id}</h2><p>${esc(o.name)} · Retrait ${clock(o.slot+(o.delay||0))}</p>${badge(o)}<p>${esc(itemtext(o.items))}</p><b>${money(total(o.items))}</b>${!['COLLECTED','CANCELLED'].includes(o.status)?'<div class="modal-actions"><button class="danger" id="cancelorder">Annuler la commande</button></div>':''}`);if($('#cancelorder'))$('#cancelorder').onclick=()=>safely(async()=>{await send('cancel',{id});$('#modal').close();render();toast('Commande annulée sur le serveur.');});};
actions.saveCapacity=()=>safely(async()=>{await send('capacity',{capacity:Number($('#capacity').value)});toast('Capacité enregistrée.');});
actions.panic=()=>safely(async()=>{if(paused()){await send('pause',{minutes:0});return toast('Prise de commandes réouverte.');}modal('<h2>Une pause pour la cuisine</h2><p>La pause s’applique immédiatement à tous les appareils.</p><div class="modal-actions">'+[15,30,60].map(n=>`<button class="danger" data-pause="${n}">${n} min</button>`).join('')+'</div>');document.querySelectorAll('[data-pause]').forEach(b=>b.onclick=()=>safely(async()=>{await send('pause',{minutes:Number(b.dataset.pause)});$('#modal').close();render();}));});
actions.checkout=()=>safely(async()=>{if(held())return payment();if(!qty(cart))return toast('Le panier est vide.');await send('reserve',{items:cart,slot:state.slots[selected]});payment();});
actions.resume=()=>payment();
actions.reset=()=>toast('La réinitialisation des données partagées est désactivée.');
payment=function(){if(!held())return toast('La réservation a expiré.');const reservationId=state.hold.id;modal(`<h2>Confirmer votre commande</h2><p>Retrait à ${clock(state.hold.slot)} · ${qty(state.hold.items)} pizza(s)</p><p>Passage n°${state.hold.sequence} · panier réservé : <b id="countdown"></b></p><label class="field">Votre prénom<input id="customer" maxlength="60" autocomplete="given-name"></label><p class="prototype">Paiement simulé · Aucun débit bancaire</p><div class="modal-actions"><button id="failpay">Annuler</button><button class="primary" id="pay">Valider ${money(total(state.hold.items))}</button></div>`);tick();$('#failpay').onclick=()=>safely(async()=>{await send('release',{reservationId});$('#modal').close();render();toast('Réservation libérée.');});$('#pay').onclick=()=>safely(async()=>{const name=$('#customer').value.trim();if(!name)return toast('Indiquez votre prénom.');const button=$('#pay');button.disabled=true;try{const r=await send('pay',{reservationId,name});cart={};$('#modal').close();render();toast(`Commande #${r.orderId} enregistrée dans la base.`);}finally{button.disabled=false;}});};
expire=function(){if(state.hold&&state.hold.expires<=Date.now()){state.hold=null;$('#modal').close();render();toast('Réservation expirée : créneau et ingrédients libérés.');refresh();}};
window.addEventListener('online',()=>{refresh(true);replay()});window.addEventListener('offline',()=>refresh());
setInterval(()=>refresh(),2000);setInterval(replay,4000);setInterval(tick,1000);setInterval(()=>{if(page==='kitchen'&&!$('#modal').open)render()},15000);
$('#app').innerHTML='<main><h1>Click Eat</h1><p>Connexion à votre pizzeria…</p></main>';refresh(true).then(replay);

function renderAccess(message){
 $('#app').innerHTML=`<div class="access-page"><a class="plain-brand" href="/">click<span>eat</span></a><section class="panel access-card"><span class="eyebrow">ESPACE PIZZERIA</span><h1>Le pilotage de votre service</h1><p>${esc(message||'Cet espace est réservé au propriétaire de la pizzeria.')}</p><a class="button-link dark" href="/signin-with-chatgpt?return_to=%2Fpilotage" target="_top">Se connecter avec ChatGPT</a><a class="back-link" href="/">Retour à la boutique client</a></section></div>`;
}
const managerRender=render;
render=function(){
 if(isPilotage){if(state.role!=='manager')return renderAccess();document.title='Click Eat · Pilotage pizzeria';managerRender();return;}
 document.title='Click Eat · Commander mes pizzas';
 $('#app').innerHTML=`<div class="client-site"><header class="client-header"><a class="plain-brand" href="/">click<span>eat</span></a><span class="restaurant-name">La Fabrique à Pizza</span><a class="back-link" href="/pilotage">Espace pizzeria ↗</a></header><main><div class="customer-identity"><span class="badge READY">Votre espace client</span><span>Identifiant client <code>${esc(state.clientId||'…')}</code></span></div>${client()}${state.reservationQueue?.[0]?`<section class="panel tracking"><h3>Dernière demande · passage n°${state.reservationQueue[0].sequence}</h3><p class="muted">${({ACCEPTED:'Réservation initialement accordée. Consultez votre panier réservé ou votre commande.',REFUSED:'Réservation refusée : '+esc(state.reservationQueue[0].reason||'stock indisponible'),PENDING:'Votre demande est en attente de traitement.',ARCHIVED:'Cette demande est archivée.'})[state.reservationQueue[0].status]}</p></section>`:''}<p class="priority-note">Stock limité : les réservations sont traitées dans leur ordre d’enregistrement au serveur. Votre numéro de passage est attribué au moment de réserver.</p><footer class="footnote"><span>Click Eat · La Fabrique à Pizza</span><span>Paiement et notifications simulés</span></footer></main></div>`;
 bind();
};
const managerNav=nav;
nav=function(p){if(p==='client'){location.href='/';return;}if(isPilotage)managerNav(p);};
const managerEnough=enough;
enough=function(items,includeHold=true){if(isPilotage)return managerEnough(items,includeHold);return Object.entries(items).every(([id,n])=>n<=(state.availability?.[id]||0));};
load=function(slot){return state.slotLoads?.[slot]||0;};
const baseOrdersView=ordersView;
ordersView=function(){return baseOrdersView()+`<section class="panel priority-panel"><div class="panelhead"><div><h2>Ordre des réservations</h2><p class="muted">30 dernières demandes · Le plus petit numéro passe en premier.</p></div></div><div class="tablewrap"><table><thead><tr><th>PASSAGE</th><th>CLIENT</th><th>REÇUE À</th><th>DÉCISION INITIALE</th></tr></thead><tbody>${(state.reservationQueue||[]).map(t=>`<tr><td><b>n°${t.sequence}</b></td><td><code class="client-id">${esc(t.clientId)}</code></td><td>${new Date(t.receivedAt).toLocaleTimeString('fr-FR')}<small>${new Date(t.receivedAt).toLocaleDateString('fr-FR')}</small></td><td><span class="badge ${t.status==='ACCEPTED'?'READY':t.status==='REFUSED'?'CANCELLED':'PREPARING'}">${{ACCEPTED:'Réservation accordée',REFUSED:'Réservation refusée',PENDING:'En attente',ARCHIVED:'Archivée'}[t.status]}</span>${t.reason?`<small>${esc(t.reason)}</small>`:''}</td></tr>`).join('')}</tbody></table>${state.reservationQueue?.length?'':'<p class="empty">Aucune demande de réservation pour le moment.</p>'}</div></section>`;};
